public abstract class AbstractPaymentProcessor implements PaymentProcessor {
    protected void completePayment(Order order, String securityCode, String paymentType) {
        System.out.println("Processing " + paymentType + " payment");
        System.out.println("Verifying security code: " + securityCode);
        order.setStatus("paid");
    }
}

public class PaypalPaymentProcessor extends AbstractPaymentProcessor {
    @Override
    public void pay(Order order, String securityCode) {
        completePayment(order, securityCode, "paypal");
    }
}

public class CreditCardPaymentProcessor extends AbstractPaymentProcessor {
    @Override
    public void pay(Order order, String securityCode) {
        completePayment(order, securityCode, "credit card");
    }
}

public class DebitCardPaymentProcessor extends AbstractPaymentProcessor {
    @Override
    public void pay(Order order, String securityCode) {
        completePayment(order, securityCode, "debit card");
    }
}
